const crypto = require('crypto');
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

// 1. Validacao obrigatoria da assinatura HMAC-SHA256 enviada pelo Backend RMM
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('N8N_WEBHOOK_SECRET nao configurado no ambiente do n8n.');
}
const receivedSig = String(headers['x-rmm-signature'] || '').replace(/^sha256=/i, '').trim();
const expectedSig = crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');
if (!receivedSig || receivedSig.length !== expectedSig.length || !crypto.timingSafeEqual(Buffer.from(receivedSig), Buffer.from(expectedSig))) {
  throw new Error('Assinatura HMAC X-RMM-Signature invalida ou ausente.');
}

// 2. Validacao de estrutura e chave de idempotencia
const idempotencyKey = String(headers['x-idempotency-key'] || body.incident_id || '').trim();
if (!idempotencyKey || !body.machine || !body.unit) {
  throw new Error('Payload de alerta invalido ou sem chave de idempotencia.');
}

// 3. Deduplicacao real em memoria persistente do workflow (TTL 30 min)
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIncidents) staticData.processedIncidents = {};
const now = Date.now();
const TTL_MS = 30 * 60 * 1000;
for (const [k, entry] of Object.entries(staticData.processedIncidents)) {
  if (!entry || now - entry.at > TTL_MS) delete staticData.processedIncidents[k];
}
if (staticData.processedIncidents[idempotencyKey]) {
  return [{ json: { duplicate: true, ticket_id: staticData.processedIncidents[idempotencyKey].ticket_id, idempotency_key: idempotencyKey } }];
}

// 4. Validacao obrigatoria do destinatario institucional (sem numero hardcoded)
const targetGroup = String($env.TI_SUPPORT_WHATSAPP_GROUP || '').trim();
if (!targetGroup) {
  throw new Error('TI_SUPPORT_WHATSAPP_GROUP nao configurado no ambiente do n8n.');
}

const ticketId = `IPO-SAUDE-${Date.now().toString().slice(-6)}`;
staticData.processedIncidents[idempotencyKey] = { ticket_id: ticketId, at: now };

const whatsappMessage = [
  `🚨 *[RMM SAÚDE IPOJUCA - ALERTA ${body.event_type}]*`,
  `🏥 *Unidade:* ${body.unit.name} (${body.unit.type})`,
  `📍 *Setor:* ${body.sector?.name || 'Geral'}`,
  `💻 *Equipamento:* ${body.machine.hostname} (${body.machine.ip_address})`,
  `⚠️ *Diagnóstico:* ${body.reason}`,
  `📊 *Métricas:* CPU ${body.metrics?.cpu_usage_pct}% | RAM ${body.metrics?.ram_usage_pct}% | HD ${body.metrics?.disk_usage_pct}%`,
  `🎫 *Chamado Aberto:* #${ticketId}`,
  `🔗 *Acesso:* ${body.dashboard_url}`
].join('\n');

return [{ json: { duplicate: false, ticket_id: ticketId, idempotency_key: idempotencyKey, target_group: targetGroup, whatsapp_text: whatsappMessage, raw_incident: body } }];
